# Generated by build.py from recipe.yml for recipe imap-enforce-a-mailbox-quota. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'newsletter.eml'), "From: shop@example.com`nTo: ann@example.com`nSubject: Our autumn newsletter`n`nNew this autumn: wool coats in five colours, boots with a lighter sole,`nand scarves woven from the same yarn as the coats. Every order over`nfifty pounds ships free until the end of the month, and returns stay`nfree for thirty days. See you in store.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'note.eml'), "From: ann@example.com`r`nTo: ann@example.com`r`nSubject: A note to self`r`n`r`nBuy a scarf to go with the grey coat, the one woven from the same yarn.`r`nAsk whether the boots with the lighter sole come in a half size.`r`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'mail.log', '--mail-domain', 'example.com', '--mailbox', '"ann@example.com:annpass;quota=1k"', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'shop@example.com:shoppass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T newsletter.eml smtp://127.0.0.1:8080/example.com
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T newsletter.eml smtp://127.0.0.1:8080/example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 2 FLAGS" imap://127.0.0.1:8081/INBOX
try { curl.exe -sS -w "%{response_code}\n" --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T newsletter.eml smtp://127.0.0.1:8080/example.com } finally { Stop-Process $server0 }
